arguments.file_text:
@using sv_2f89606524b7476ca6c06f23fdcd1848.Models

<aside class="thread-panel">
    <div class="thread-header">
        <h4>Thread</h4>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <div class="root-author">@RootMessage.Author</div>
            <div class="root-content">@RootMessage.Content</div>
        </div>

        <div class="thread-divider">
            <span>@ThreadMessages.Count @(ThreadMessages.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-messages">
            @foreach (var msg in ThreadMessages)
            {
                <div class="thread-reply">
                    <div class="reply-header">
                        <span class="reply-author">@msg.Author</span>
                        <span class="reply-time">@FormatRelativeTime(msg.SentAt)</span>
                    </div>
                    <div class="reply-content">@msg.Content</div>
                </div>
            }
        </div>
    }

    <MessageInput Placeholder="Reply in thread…"
                  ButtonLabel="Reply"
                  OnSubmit="OnReply" />
</aside>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> ThreadMessages { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReply { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;

        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }
}

.thread-panel {
    width: 100%;
    height: 100%;
    background-color: #313338;
    border-left: 1px solid #3f4147;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
}

.thread-header h4 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #e0e0e0;
}

.close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background-color 0.15s;
}

.close-btn:hover {
    background-color: rgba(255, 255, 255, 0.08);
    color: #e0e0e0;
}

.thread-root {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    background-color: rgba(255, 255, 255, 0.02);
}

.root-author {
    font-weight: 600;
    font-size: 0.9rem;
    color: #f0f0f0;
    margin-bottom: 4px;
}

.root-content {
    font-size: 0.85rem;
    color: #dcddde;
    line-height: 1.4;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-divider {
    padding: 8px 16px;
    font-size: 0.75rem;
    color: #72767d;
    border-bottom: 1px solid #3f4147;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.thread-reply {
    padding: 8px 16px;
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.reply-author {
    font-weight: 600;
    font-size: 0.85rem;
    color: #f0f0f0;
}

.reply-time {
    font-size: 0.7rem;
    color: #72767d;
