@using sv_2f89606524b7476ca6c06f23fdcd1848.Models

<section class="message-area">
    <div class="area-header">
        <h3># @ChannelName</h3>
        <span class="area-description">@ChannelDescription</span>
    </div>

    <div class="message-list" @onscroll="HandleScroll" @ref="_messageListRef">
        @if (_loadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         ReplyCount="GetReplyCount(message.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")"
                  ButtonLabel="Send"
                  OnSubmit="OnSendMessage" />
</section>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadOlderMessages { get; set; }

    private ElementReference _messageListRef;
    private bool _loadingMore;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.GetValueOrDefault(messageId, 0);

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers loading older messages
        // JS interop would be ideal for precise scroll detection, but we use
        // a simple approach: fire event and let the parent decide
        // The parent handles debouncing via the _loadingMore flag
    }

    public void SetLoadingMore(bool loading)
    {
        _loadingMore = loading;
        StateHasChanged();
    }
}

