arguments.file_text:
@page "/chat"
@using sv_2f89606524b7476ca6c06f23fdcd1848.Models
@using sv_2f89606524b7476ca6c06f23fdcd1848.Components.Chat
@rendermode InteractiveServer
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_activeChannelId"
                        OnChannelSelected="SelectChannelAsync" />
    </div>

    <div class="chat-main @(_isThreadOpen ? "" : "expanded")">
        @if (_activeChannel is not null)
        {
            <MessageArea ChannelName="@_activeChannel.Name"
                         ChannelDescription="@_activeChannel.Description"
                         Messages="_messages"
                         ThreadReplyCounts="_threadReplyCounts"
                         OnOpenThread="OpenThreadAsync"
                         OnReact="HandleReactionAsync"
                         OnSendMessage="SendMessageAsync" />
        }
        else
        {
            <div class="empty-state">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_isThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnClose="CloseThread"
                         OnReply="SendThreadReplyAsync" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private int _activeChannelId;
    private Channel? _activeChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = [];
    private bool _isThreadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadMessages = [];
    private int _messagesSkip;
    private bool _loadingMore;
    private bool _allMessagesLoaded;

    private IJSObjectReference? _jsModule;
    private DotNetObjectReference<Chat>? _selfRef;

    private const int PageSize = 50;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();

        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0].Id);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
                "./_content/sv-2f89606524b7476ca6c06f23fdcd1848/Components/Pages/Chat.razor.js");
            _selfRef = DotNetObjectReference.Create(this);
            await _jsModule.InvokeVoidAsync("initScrollWatcher", _selfRef);
        }
    }

    private async Task SelectChannelAsync(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messagesSkip = 0;
        _allMessagesLoaded = false;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messagesSkip = _messages.Count;

        BuildThreadReplyCounts();

        await ChatService.MarkChannelReadAsync(channelId);
        // Refresh channel list to update unread badge
        _channels = await ChatService.GetChannelsAsync();

        if (_jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("scrollToBottom");
        }
    }

    [JSInvokable]
    public async Task LoadOlderMessages()
    {
        if (_loadingMore || _allMessagesLoaded || _activeChannel is null) return;

        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messagesSkip, PageSize);

        if (older.Count < PageSize)
        {
            _allMessagesLoaded = true;
        }

        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _messagesSkip += older.Count;
            BuildThreadReplyCounts();
        }

        _loadingMore = false;
        StateHasChanged();
    }

    private async Task SendMessageAsync(string content)
    {
        if (_activeChannel is null) return;

        var message = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(message);
        _messagesSkip++;
        StateHasChanged();

        if (_jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("scrollToBottom");
        }
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _isThreadOpen = true;
    }

    private void CloseThread()
    {
        _isThreadOpen = false;
        _threadRootMessage = null;
        _threadMessages = [];
    }

    private async Task SendThreadReplyAsync(string content)
    {
        if (_threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(
            _activeChannelId, content, _threadRootMessage.Id);
        _threadMessages.Add(reply);

        // Update reply count
        if (_threadReplyCounts.ContainsKey(_threadRootMessage.Id))
        {
            _threadReplyCounts[_threadRootMessage.Id]++;
        }
        else
        {
            _threadReplyCounts[_threadRootMessage.Id] = 1;
        }
    }

    private async Task HandleReactionAsync((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Update local message state
        var message = _messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (message is not null)
        {
            var existingReaction = message.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existingReaction is not null)
            {
                if (!existingReaction.Users.Contains("You"))
                {
                    existingReaction.Users.Add("You");
                }
            }
            else
            {
                message.Reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
        }
    }

    private void BuildThreadReplyCounts()
    {
        _threadReplyCounts = _messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());
    }

    public async ValueTask DisposeAsync()
    {
        _selfRef?.Dispose();
        if (_jsModule is not null)
        {
            await _jsModule.DisposeAsync();
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    width: 100%;
    overflow: hidden;
    background-color: #313338;
    color: #dcddde;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.chat-main.expanded {
    flex: 1;
}

.chat-thread {
    width: 25%;
    min-width: 260px;
    max-width: 400px;
    flex-shrink: 0;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #72767d;
    font-size: 1.1rem;
}

::deep .message-list {
    scrollbar-width: thin;
    scrollbar-color: #1a1b1e transparent;
}

let dotNetRef = null;

export function initScrollWatcher(ref) {
    dotNetRef = ref;
    const list = document.querySelector('.message-list');
    if (!list) return;

    list.addEventListener('scroll', () => {
        if (list.scrollTop === 0 && dotNetRef) {
            dotNetRef.invokeMethodAsync('LoadOlderMessages');
        }
    });
}

export function scrollToBottom() {
    requestAnimationFrame(() => {
        const list = document.querySelector('.message-list');
        if (list) {
            list.scrollTop = list.scrollHeight;
        }
    });
}

