.chat-layout {
    display: flex;
    height: 100vh;
    width: 100%;
    overflow: hidden;
    background-color: #313338;
    color: #dcddde;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.chat-main.expanded {
    flex: 1;
}

.chat-thread {
    width: 25%;
    min-width: 260px;
    max-width: 400px;
    flex-shrink: 0;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #72767d;
    font-size: 1.1rem;
}

::deep .message-list {
    scrollbar-width: thin;
    scrollbar-color: #1a1b1e transparent;
}

let dotNetRef = null;

export function initScrollWatcher(ref) {
    dotNetRef = ref;
    const list = document.querySelector('.message-list');
    if (!list) return;

    list.addEventListener('scroll', () => {
        if (list.scrollTop === 0 && dotNetRef) {
            dotNetRef.invokeMethodAsync('LoadOlderMessages');
        }
    });
}

export function scrollToBottom() {
    requestAnimationFrame(() => {
        const list = document.querySelector('.message-list');
        if (list) {
            list.scrollTop = list.scrollHeight;
        }
    });
}

